  "Königlich": "Realeza",
  "Stelle einen königlichen Edelstein her": "Crea una gema real",
  "Reingelegt": "¡Sorpresa!",
  "Besiege einen Mimik": "Derrota a un mímico",
  "Goldrausch": "Fiebre del oro",
  "Erwische einen Schatzgoblin": "Atrapa a un goblin del tesoro",
