  "Baue dein Versteck auf insgesamt Stufe 10 aus": "Mejora tu Guarida hasta un nivel total de 10",
  "Festung Klingenhort": "Fortaleza Klingenhort",
  "Baue dein Versteck auf insgesamt Stufe 30 aus": "Mejora tu Guarida hasta un nivel total de 30",
