  "Noch keine Bauteile. Gegner lassen manchmal welche fallen (Elite und Bosse öfter) – oder zerlege Gegenstände.": "Aún no tienes piezas. Los enemigos a veces las sueltan (la élite y los jefes, más a menudo)… o desmonta objetos.",
