  "Ein Schutzschild fängt einige Sekunden lang Schaden für dich ab.": "Un escudo protector absorbe el daño por ti durante unos segundos.",
  "Ein Kettenblitz springt durch viele Gegner.": "Un rayo en cadena salta entre muchos enemigos.",
  "Friert alle Gegner um den Begleiter ein.": "Congela a todos los enemigos alrededor del compañero.",
  "Eine Wolke, die alle Gegner darin vergiftet.": "Una nube que envenena a todos los enemigos que haya dentro.",
  "Meteor": "Meteoro",
  "Ein Meteor schlägt ein und trifft alles in der Nähe hart.": "Un meteoro cae y golpea con fuerza todo lo que hay cerca.",
  "Rankenfessel": "Atadura de zarzas",
  "Dornenranken fesseln Gegner und verletzen sie.": "Zarzas espinosas atrapan a los enemigos y los hieren.",
  "Mondschein": "Luz de luna",
  "Bernstein": "Ámbar",
  "Türkis": "Turquesa",
  "Klassisch": "Clásico",
  "Schillernd": "Tornasol",
  "Sammlung: {n} Arten entdeckt! +{c} Glücksmünzen": "Colección: ¡{n} especies descubiertas! +{c} Monedas de la Fortuna",
  "Dein Brutnest ist voll – mehr als {n} Eier passen nicht hinein.": "Tu nido está lleno: no caben más de {n} huevos.",
  "{egg}! Pflege es im Brutnest, dann schlüpft es.": "¡{egg}! Cuídalo en el Nido y eclosionará.",
  "aus der Zucht": "de cría",
  "{name} · LV {lv} · {stage}": "{name} · LV {lv} · {stage}",
  "Passive Kraft": "Poder pasivo",
  "Spezialangriff": "Ataque especial",
  "Uralte Kraft": "Poder ancestral",
  "Mythische Kraft": "Poder mítico",
  "{name} ENTWICKELT SICH!": "¡{name} EVOLUCIONA!",
  "{stage} · LV {lv} · Neu: {what} und eine neue Farbe": "{stage} · LV {lv} · Nuevo: {what} y un color nuevo",
  "LV {lv}": "LV {lv}",
  "{name} erreicht LV {lv}!": "¡{name} sube a LV {lv}!",
  "Geschlüpft: {what}": "Eclosión: {what}",
  "Ein schillernder {name}! (1 zu 100)": "¡{name} tornasol! (1 entre 100)",
  "Wähle zwei Begleiter.": "Elige dos compañeros.",
  "Erst ab LV {lv} zuchtreif.": "Solo puede criar desde LV {lv}.",
  "Verletzt.": "Herido.",
  "Ruht sich noch {t} aus.": "Descansa aún {t}.",
  "Wähle zwei verschiedene Begleiter.": "Elige dos compañeros distintos.",
  "Dir fehlt Gold: {n} nötig.": "Te falta oro: necesitas {n}.",
  "MONSTER-EI!": "¡HUEVO DE MONSTRUO!",
  "RUNE: {n}": "RUNA: {n}",
  "Zauberrune für deinen Begleiter: {n}": "Runa mágica para tu compañero: {n}",
  "Begleiter-Ausrüstung: {n} ({r})": "Equipo de compañero: {n} ({r})",
  "BEGLEITER-EI!": "¡UN HUEVO!",
  "{egg}! Bring es ins Brutnest im Versteck.": "¡{egg}! Llévalo al Nido de la Guarida.",
  "Ein Begleiter-Ei! Dein Brutnest ist voll – dafür +1 Glücksmünze.": "¡Un huevo de compañero! Tu nido está lleno: a cambio, +1 Moneda de la Fortuna.",
  "SCHILD": "ESCUDO",
  "Nestmutter Gunda": "Cuidadora Gunda",
  "Wärme, Futter, Zuwendung. Fehlt eins davon, schläft das Küken im Ei einfach weiter.": "Calor, comida y cariño. Si falta uno, el polluelo sigue durmiendo dentro del huevo.",
  "Sind alle drei Bedürfnisse gut gefüllt, wächst ein Ei anderthalbmal so schnell.": "Si las tres necesidades están bien cubiertas, el huevo crece una vez y media más rápido.",
  "Streichle die Eier ruhig. Die spüren das. Wirklich.": "Acaricia los huevos sin miedo. Lo notan. De verdad.",
  "Aus einem schmutzigen Ei schlüpft meist eine Schnecke. Aber man liebt sie trotzdem.": "De un huevo sucio suele salir un caracol. Pero se le quiere igual.",
  "Ein mythisches Ei braucht Tage. Und Sternenstaub. Und Geduld. Vor allem Geduld.": "Un huevo mítico necesita días. Y polvo de estrellas. Y paciencia. Sobre todo, paciencia.",
  "Brutnest: Ein Ei ist bereit zum Schlüpfen!": "Nido: ¡un huevo está listo para eclosionar!",
  "Brutnest: {n} Eier sind bereit zum Schlüpfen!": "Nido: ¡{n} huevos están listos para eclosionar!",
  "Brutnest: Ein Ei braucht dich – es wächst gerade nicht.": "Nido: un huevo te necesita; ahora mismo no crece.",
  "Brutnest: {n} Eier brauchen dich – sie wachsen gerade nicht.": "Nido: {n} huevos te necesitan; ahora mismo no crecen.",
  "BEREIT": "LISTO",
  "Ein Ei! Das hast du dem Boss abgenommen? Bring es zu mir ins Brutnest – ich wohne jetzt im Versteck.": "¡Un huevo! ¿Se lo has quitado al jefe? Tráemelo al Nido: ahora vivo en la Guarida.",
  "Ein Ei! Wo hast du das denn gefunden? Bring es zu mir ins Brutnest – ich wohne jetzt im Versteck.": "¡Un huevo! ¿Dónde lo has encontrado? Tráemelo al Nido: ahora vivo en la Guarida.",
  "Halt es warm, füttere es und schenk ihm Zuwendung. Dann wächst es – auch während du unterwegs bist.": "Mantenlo caliente, dale de comer y dale cariño. Así crecerá, incluso mientras estás de viaje.",
  "Irgendwann schlüpft daraus dein erster Begleiter. Komm, ich zeig dir das Nest.": "Algún día saldrá de él tu primer compañero. Ven, te enseño el nido.",
  "Ich bin Gunda und kümmere mich ab jetzt um das Brutnest im Versteck.": "Soy Gunda y, a partir de ahora, me ocupo del Nido de la Guarida.",
  "Eier schlüpfen nicht mehr von allein: Halt sie warm, füttere sie und schenk ihnen Zuwendung. Dann wachsen sie, auch während du unterwegs bist.": "Los huevos ya no eclosionan solos: mantenlos calientes, dales de comer y dales cariño. Así crecerán, incluso mientras estás de viaje.",
  "DEIN ERSTES EI": "TU PRIMER HUEVO",
  "NEU: DAS BRUTNEST": "NUEVO: EL NIDO",
