  "BEUTEL {n}/{max}": "BOLSA {n}/{max}",
  "Fällst du in den Verlorenen Landen, rettet dein Begleiter, was in seinem Beutel liegt. Seltenere Arten tragen mehr, das Talent „Große Taschen“ gibt weitere Plätze.": "Si caes en las Tierras Perdidas, tu compañero salva lo que lleve en su bolsa. Las especies más raras cargan más, y el talento «Bolsillos grandes» da más espacios.",
  "Alles herausnehmen": "Sacar todo",
  "Verletzt – ruht sich im Versteck aus. Wieder fit in {t}.": "Herido: descansa en la Guarida. Estará en forma en {t}.",
  "Heiltrank geben": "Dar poción de vida",
  "Heilbrei ({n}× {mat})": "Ungüento ({n}× {mat})",
  "Ruht im Korb": "Descansa en la cesta",
  "Bereit zum Schlüpfen!": "¡Listo para eclosionar!",
  "Wächst · noch {t} Pflege": "Crece · faltan {t} de cuidados",
  "Pausiert – braucht Pflege": "En pausa: necesita cuidados",
  "EIER {n}/{max}": "HUEVOS {n}/{max}",
  "Noch keine Eier. Das erste gibt es vom ersten Boss der Geschichte, weitere von Bossen, der Drachentruhe, aus den Verlorenen Landen und vom Basar.": "Aún no tienes huevos. El primero te lo da el primer jefe de la historia; los demás salen de los jefes, el Cofre del Dragón, las Tierras Perdidas y el Bazar.",
  "Zum Brutnest": "Ir al Nido",
  "SAMMLUNG {n}/{max}": "COLECCIÓN {n}/{max}",
  "Nächste Belohnung: {n} Arten entdeckt → +{c} Glücksmünzen": "Siguiente recompensa: {n} especies descubiertas → +{c} Monedas de la Fortuna",
  "Alle Arten entdeckt!": "¡Todas las especies descubiertas!",
  "HYBRIDE {n}/{max}": "HÍBRIDOS {n}/{max}",
  "Gibt es nur aus der Zucht – das Zuchtbuch verrät, wer zusammenpasst.": "Solo se obtienen por cría: el libro de cría revela quién combina con quién.",
