  "ALLE RÄNGE": "VER RANGOS",
  "Füge zuerst einen Tauschcode oder Tauschlink ein.": "Primero pega un código o un enlace de intercambio.",
  "Das ist kein Tauschcode. Ein Tauschcode beginnt mit „KH5-“.": "Eso no es un código de intercambio. Los códigos de intercambio empiezan por «KH5-».",
  "Der Code ist beschädigt oder unvollständig. Bitte noch einmal ganz kopieren.": "El código está dañado o incompleto. Vuelve a copiarlo entero.",
  "Der Code enthält ungültige Daten und kann nicht eingelöst werden.": "El código contiene datos no válidos y no se puede canjear.",
  "Diesen Code hast du schon eingelöst. Jeder Code gilt nur einmal.": "Ya canjeaste este código. Cada código sirve una sola vez.",
  "Das ist dein eigener Tauschcode – schick ihn einem Freund.": "Es tu propio código de intercambio: envíaselo a un amigo.",
  "Wähle zuerst einen Helden, der das Geschenk bekommt.": "Primero elige el héroe que recibirá el regalo.",
  "Dein Beutel ist voll (30/30). Mach Platz und versuch es noch einmal.": "Tu bolsa está llena (30/30). Haz sitio y vuelve a intentarlo.",
  "In diesem Code steckt ein Begleiter – diese Version kann ihn noch nicht annehmen. Der Code bleibt gültig.": "Este código contiene un compañero, pero esta versión aún no puede recibirlo. El código sigue siendo válido.",
  "Kein Platz für einen weiteren Begleiter. Der Code bleibt gültig.": "No hay sitio para otro compañero. El código sigue siendo válido.",
  "Der Begleiter konnte nicht übernommen werden. Der Code bleibt gültig.": "No se pudo recibir al compañero. El código sigue siendo válido.",
  "Das hat nicht geklappt.": "Algo salió mal.",
  "Tauschcode erkannt – du findest ihn im Hauptmenü unter „Tausch empfangen“.": "Código de intercambio detectado: lo encontrarás en el menú principal, en «Canjear código».",
