  "Du hast noch keine Materialien, Edelsteine oder Bauteile.": "Aún no tienes materiales, gemas ni piezas.",
  "Schieb die Regler: So viel kommt ins Bündel.": "Desliza las barras para elegir cuánto va en el lote.",
