  "EIER": "HUEVOS",
  "Beim Verschenken beginnt das Ausbrüten von vorn.": "Al regalarlo, la incubación empieza de cero.",
  "Noch nichts ausgewählt.": "Aún no has elegido nada.",
  "„{name}“ verlässt deinen Beutel. Daraus wird ein Tauschcode, den genau eine Person einlösen kann.": "«{name}» saldrá de tu bolsa y se convertirá en un código de intercambio que solo una persona podrá canjear.",
  "Diese Dinge verlassen deinen Vorrat. Daraus wird ein Tauschcode, den genau eine Person einlösen kann.": "Estas cosas saldrán de tus recursos y se convertirán en un código de intercambio que solo una persona podrá canjear.",
