  "Man sagt, {name} habe einst {deed}.": "Dicen que {name} una vez {deed}.",
  "Seit {n} Wintern haust {name} in {place}.": "Desde hace {n} inviernos, {name} mora en {place}.",
  "{name} sammelt {thing} – und die Knochen derer, die danach fragen.": "{name} colecciona {thing}… y los huesos de quien pregunta por su colección.",
  "Wer {name} begegnet, hört zuerst {sound}.": "Quien se cruza con {name} oye primero {sound}.",
  "Die Kundschafter meiden {place}, seit {name} dort erwacht ist.": "Los exploradores evitan {place} desde que {name} despertó allí.",
  "{name} fürchtet nur eines: {fear}.": "{name} solo teme una cosa: {fear}.",
  "Alte Lieder erzählen, {name} sei aus {origin} geboren.": "Las viejas canciones cuentan que {name} nació {origin}.",
  "Auf {name} steht ein Kopfgeld von {g} Gold. Niemand hat es je abgeholt.": "Hay una recompensa de {g} de oro por {name}. Nadie la ha cobrado jamás.",
  "Die Karten des Ordens nennen {place} nur „das Revier von {name}“.": "Los mapas de la Orden llaman a {place} solo «el territorio de {name}».",
  "{name} spricht nie. Doch in {place} flüstern die Steine diesen Namen.": "{name} nunca habla. Pero en {place} las piedras susurran su nombre.",
  "ein ganzes Heer in Stein verwandelt": "convirtió en piedra a todo un ejército",
  "den Mond eine Nacht lang verschluckt": "se tragó la luna durante una noche entera",
  "drei Könige an einem Tag gestürzt": "derrocó a tres reyes en un solo día",
  "eine Stadt unter Eis begraben": "sepultó una ciudad bajo el hielo",
  "einen Fluss zum Kochen gebracht": "hizo hervir un río",
  "hundert Ritter des Ordens besiegt": "derrotó a cien caballeros de la Orden",
  "einen Drachen mit bloßen Händen bezwungen": "venció a un dragón con las manos desnudas",
  "ein Tor der Alten versiegelt": "selló un portal de los Antiguos",
  "die Sonne einen Tag lang verdunkelt": "oscureció el sol durante un día entero",
  "einen Wald in Asche gelegt": "redujo un bosque a cenizas",
  "einen Gott betrogen": "engañó a un dios",
  "die Toten eines ganzen Tals geweckt": "despertó a los muertos de todo un valle",
  "eine Flotte im Sturm versenkt": "hundió una flota en plena tormenta",
  "den Schatz eines Zwergenkönigs gestohlen": "robó el tesoro de un rey enano",
  "Kronen gefallener Könige": "coronas de reyes caídos",
  "Zähne von Drachen": "dientes de dragón",
  "Glocken versunkener Tempel": "campanas de templos hundidos",
  "zerbrochene Schwerter": "espadas rotas",
  "leuchtende Steine": "piedras luminosas",
  "die Schädel von Helden": "los cráneos de los héroes",
  "alte Karten der Lande": "viejos mapas de las Tierras",
  "gestohlene Sterne": "estrellas robadas",
  "Federn des Phönix": "plumas de fénix",
  "die Rüstungen des Ordens": "las armaduras de la Orden",
  "ein fernes Glockenläuten": "un lejano tañido de campanas",
  "das Knirschen von Eis": "el crujido del hielo",
  "ein leises Lachen": "una risa queda",
  "das Rasseln schwerer Ketten": "el traqueteo de cadenas pesadas",
  "das Summen tausender Fliegen": "el zumbido de mil moscas",
  "Donner aus klarem Himmel": "un trueno con el cielo despejado",
  "ein altes Wiegenlied": "una vieja canción de cuna",
  "das Knistern von Feuer": "el crepitar del fuego",
  "Sonnenlicht": "la luz del sol",
  "Lieder über Helden": "las canciones de héroes",
  "den Klang von Silber": "el sonido de la plata",
  "Spiegel": "los espejos",
  "die Stille": "el silencio",
  "Kinderlachen": "la risa de los niños",
  "frisches Wasser": "el agua fresca",
  "das Licht der Sterne": "la luz de las estrellas",
  "der ersten Flamme": "de la primera llama",
  "dem Schlamm der Urzeit": "del fango primigenio",
  "einem zerbrochenen Stern": "de una estrella rota",
  "dem letzten Atemzug eines Gottes": "del último aliento de un dios",
  "einem Fluch des Ordens": "de una maldición de la Orden",
  "der tiefsten Gruft": "de la cripta más profunda",
  "einem Riss in der Leere": "de una grieta en el Vacío",
  "den Tränen eines Riesen": "de las lágrimas de un gigante",
