  "Heiltotem": "Tótem curativo",
  "Ein eisiger Ring um den Boss friert ein, wer drinsteht. Raus aus dem Kreis!": "Un anillo helado alrededor del jefe congela a quien esté dentro. ¡Sal del círculo!",
  "Meteorregen": "Lluvia de meteoros",
  "Brennende Felsen fallen vom Himmel. Die Kreise zeigen, wo sie einschlagen.": "Rocas ardientes caen del cielo. Los círculos marcan dónde impactarán.",
  "Schockwellen": "Ondas de choque",
  "Der Boss stampft – Wellen rollen nach außen. Rolle durch die Welle oder bleib außer Reichweite.": "El jefe da un pisotón y las ondas se expanden. Rueda a través de la onda o mantente fuera de su alcance.",
  "Tipp: Während du rollst, kann dich nichts treffen – rolle durch Wellen hindurch!": "Consejo: mientras ruedas, nada puede alcanzarte. ¡Rueda a través de las ondas!",
  "Eine Bahn zeigt, wohin der Boss gleich stürmt. Geh zur Seite!": "Una franja muestra hacia dónde va a cargar el jefe. ¡Apártate!",
  "Beschwörung": "Invocación",
  "Aus Portalen kriechen Diener. Erledige sie, bevor es zu viele werden.": "De los portales salen esbirros. Acaba con ellos antes de que sean demasiados.",
  "Schutzschild": "Escudo",
  "Ein Schild schluckt viel Schaden. Brich ihn – dann ist der Boss kurz benommen.": "Un escudo absorbe mucho daño. Rómpelo y el jefe quedará aturdido un momento.",
  "Tipp: Brich den Schild – dann ist der Boss ein paar Sekunden benommen.": "Consejo: rompe el escudo y el jefe quedará aturdido unos segundos.",
  "Der Boss verschwindet und taucht am markierten Ort wieder auf – mit einem Schlag.": "El jefe desaparece y reaparece en el lugar marcado… con un golpe.",
  "Giftwolken": "Nubes tóxicas",
  "Giftblasen platzen und hinterlassen Wolken, die lange brennen.": "Burbujas de veneno estallan y dejan nubes que queman durante mucho tiempo.",
  "Blitzschlag": "Relámpago",
  "Ein Zeichen folgt dir und bleibt dann stehen – lauf weg, bevor der Blitz einschlägt.": "Una marca te sigue y luego se detiene: huye antes de que caiga el rayo.",
  "Tipp: Das Zeichen folgt dir – sobald es stehen bleibt, lauf weg!": "Consejo: la marca te sigue; en cuanto se detenga, ¡huye!",
  "Atemstoß": "Aliento",
  "Ein Fächer vor dem Boss wird gleich in Feuer, Eis oder Gift getaucht. Geh hinter ihn oder zur Seite.": "Un abanico delante del jefe va a llenarse de fuego, hielo o veneno. Ponte detrás de él o a un lado.",
  "Todessprung": "Salto mortal",
  "Der Boss springt dorthin, wo du stehst. Der Schatten am Boden zeigt die Landung.": "El jefe salta hacia donde estás. La sombra en el suelo marca dónde aterrizará.",
  "Kugelring": "Anillo de orbes",
  "Ein Ring aus Geschossen fliegt nach außen. Stell dich in eine Lücke.": "Un anillo de proyectiles se expande hacia fuera. Colócate en un hueco.",
  "Kreuzschnitt": "Corte en cruz",
  "Leuchtende Linien durch den Boss werden gleich zu Klingen. Weg von den Linien!": "Unas líneas brillantes que atraviesan al jefe van a convertirse en cuchillas. ¡Aléjate de las líneas!",
  "Erdspalten": "Grietas",
  "Der Boden reißt vom Boss in deine Richtung auf. Geh aus der Spur.": "El suelo se abre desde el jefe hacia ti. Sal de su trayectoria.",
  "Klingenwirbel": "Remolino de hojas",
  "Klingen kreisen um den Boss. Erst sind sie blass – dann schneiden sie.": "Unas hojas giran alrededor del jefe. Primero son pálidas… luego cortan.",
  "Ein ganzes Feld fängt Feuer. Verlass die markierte Fläche schnell.": "Todo un campo arde. Sal rápido de la zona marcada.",
  "Lebensraub": "Robo de vida",
  "Im Kreis um den Boss saugt er dir Leben aus und heilt sich. Verlass den Kreis.": "Dentro del círculo que lo rodea, el jefe te absorbe la vida y se cura. Sal del círculo.",
  "Tipp: Verlass den roten Kreis, dann reißt der Lebensraub ab.": "Consejo: sal del círculo rojo y el robo de vida se cortará.",
  "Unter 30 % Leben wird der Boss schneller und stärker.": "Por debajo del 30 % de vida, el jefe se vuelve más rápido y más fuerte.",
  "Phasen": "Fases",
  "Bei 66 % und 33 % Leben stößt der Boss alle zurück und kämpft danach schneller – manchmal mit neuen Kräften.": "Al 66 % y al 33 % de vida, el jefe empuja a todos hacia atrás y después lucha más rápido, a veces con nuevos poderes.",
  "Seelenjäger": "Cazalmas",
  "Langsame Geister verfolgen dich. Weiche aus oder zerschlag sie mit Nahkampfhieben.": "Espíritus lentos te persiguen. Esquívalos o destrózalos con golpes cuerpo a cuerpo.",
  "Sprengsaat": "Siembra explosiva",
  "Der Boss verstreut Minen. Kommst du zu nah, zünden sie – der rote Kreis zeigt die Explosion.": "El jefe esparce minas. Si te acercas demasiado, estallan: el círculo rojo muestra la explosión.",
  "Der Boss heilt sich. Viel Schaden in kurzer Zeit unterbricht ihn.": "El jefe se cura. Mucho daño en poco tiempo lo interrumpe.",
  "Tipp: Viel Schaden in kurzer Zeit unterbricht die Heilung.": "Consejo: mucho daño en poco tiempo interrumpe la curación.",
  "Heiltotems": "Tótems curativos",
  "Totems heilen den Boss, solange sie stehen. Zerstöre sie zuerst.": "Los tótems curan al jefe mientras sigan en pie. Destrúyelos primero.",
  "Tipp: Die Totems heilen den Boss – zerstöre sie zuerst!": "Consejo: los tótems curan al jefe. ¡Destrúyelos primero!",
  "Sog": "Vórtice",
  "Der Boss zieht dich zu sich – in seiner Mitte wartet Schaden. Lauf dagegen an.": "El jefe te atrae hacia sí, y en su centro te espera el daño. Corre en sentido contrario.",
  "Kugelspirale": "Espiral de orbes",
  "Drehende Arme aus Geschossen. Bewege dich mit der Drehung.": "Brazos giratorios de proyectiles. Muévete con el giro.",
  "Blitze springen zwischen Punkten um dich herum. Stell dich nicht auf eine Linie.": "Los rayos saltan entre puntos a tu alrededor. No te quedes en línea con ellos.",
  "Spiegelbilder": "Reflejos",
  "Trugbilder des Bosses erscheinen. Nur der echte leuchtet und hat den Lebensbalken oben.": "Aparecen ilusiones del jefe. Solo el verdadero brilla y tiene la barra de vida arriba.",
  "Tipp: Nur der echte Boss hat den leuchtenden Rand – die Trugbilder zerfallen schnell.": "Consejo: solo el jefe verdadero tiene el borde brillante; las ilusiones se deshacen rápido.",
  "Todesstrahl": "Rayo mortal",
  "Eine dünne Linie zeigt den Strahl an – dann dreht er sich durch die Arena. Bleib hinter ihm.": "Una línea fina anuncia el rayo; luego gira por la arena. Quédate detrás de él.",
  "Finsternis": "Tinieblas",
  "Alle Lichter erlöschen für ein paar Sekunden. Gefahren leuchten trotzdem.": "Todas las luces se apagan unos segundos. Los peligros siguen brillando.",
  "Tipp: Farbige Flächen zeigen, wo gleich Schaden kommt. Raus da, bevor sie aufleuchten!": "Consejo: las zonas de color muestran dónde va a caer el daño. ¡Sal de ahí antes de que se iluminen!",
  "Mutiges Herz": "Corazón valiente",
  "Schrecken der Höhlen": "Terror de las cuevas",
  "Geißel der Ungeheuer": "Azote de monstruos",
  "Hammer der Bosse": "Martillo de jefes",
  "Legende der Lande": "Leyenda de las Tierras",
  "Albtraum der Tyrannen": "Pesadilla de tiranos",
  "Stern der Jagd": "Estrella de la caza",
  "Erbe des Ordens": "Legado de la Orden",
  "Sturm der Tausend": "Tormenta de los Mil",
  "Unsterbliche Legende": "Leyenda inmortal",
  "Ende aller Bosse": "Fin de todos los jefes",
