  "ÜBUNG GESCHAFFT": "PRÁCTICA SUPERADA",
  "BOSS BESIEGT": "JEFE DERROTADO",
  "BESIEGT": "DERROTADO",
  "{name} war diesmal stärker. Im Boss-Kodex stehen alle Mechaniken – Übung macht den Meister.": "Esta vez {name} ha sido más fuerte. En el Códice de jefes están todas las mecánicas: la práctica hace al maestro.",
  "Nochmal": "Otra vez",
  "Zum Boss-Kodex": "Ir al Códice",
  "Nächster Bonus bei {n} Trophäen: {b}": "Próximo bonus con {n} trofeos: {b}",
  "Alle Trophäen-Boni freigeschaltet!": "¡Todos los bonus de trofeos desbloqueados!",
  "Unbekannter Boss, Rang {n}": "Jefe desconocido, rango {n}",
  "Tippe einen Boss an. Unbekannte zeigen nur ihren Schatten – finde ihre Höhlen in den Endlosen Landen.": "Toca un jefe. Los desconocidos solo muestran su sombra: encuentra sus cuevas en las Tierras Infinitas.",
  "BOSS-KODEX": "CÓDICE DE JEFES",
