  "Hier ist noch nichts.": "Aquí aún no hay nada.",
  "Höhlen dieses Rangs liegen etwa {d} % tief in den Endlosen Landen.": "Las cuevas de este rango están a un {d} % de profundidad en las Tierras Infinitas.",
