  "Besiege den Boss, um sie zu sehen. Garantiert beim ersten Sieg.": "Derrota al jefe para verlo. Garantizado en la primera victoria.",
  "Übungskampf": "Práctica",
  "Ohne Beute und ohne Risiko – zum Lernen der Mechaniken.": "Sin botín y sin riesgo: para aprender las mecánicas.",
