  "{mod} {t}": "{mod} {t}",
  "Mod gefunden: {mod}": "Mod encontrado: {mod}",
  "Dein erster Mod! Setz ihn an einer Werkbank oder in der Schmiede ein: VERBESSERN → MODS.": "¡Tu primer mod! Colócalo en un Banco de trabajo o en la Forja: POTENCIAR → MODS.",
  "{n} G": "{n} O",
  "{p} je Treffer: Kettenblitz auf {n} Gegner, je {v} Waffenschaden": "{p} de prob. por golpe: Rayo en cadena a {n} enemigos, {v} del daño del arma a cada uno",
  "{p} je Treffer: Frostnova um das Ziel ({v} Waffenschaden), friert {s} s ein": "{p} de prob. por golpe: Nova de escarcha alrededor del objetivo ({v} del daño del arma), congela {s} s",
  "Jeder Kill heilt {v} deiner LP": "Cada baja te cura {v} de tus PV",
  "{p} je Kill: ein Geist kämpft {s} s mit": "{p} de prob. por baja: un espíritu lucha a tu lado {s} s",
  "{p} je Treffer: Blutung, 4 s lang je Sekunde {v} Waffenschaden": "{p} de prob. por golpe: sangrado, {v} del daño del arma por segundo durante 4 s",
  "{p} je Kill: der Gegner explodiert ({v} Waffenschaden ringsum)": "{p} de prob. por baja: el enemigo explota ({v} del daño del arma alrededor)",
  "{p} je kritischem Treffer: ein Meteor schlägt ein ({v} Waffenschaden)": "{p} de prob. por crítico: cae un meteoro ({v} del daño del arma)",
  "{p} je Treffer: eine Schattenklinge trifft noch einmal ({v} Waffenschaden)": "{p} de prob. por golpe: una hoja de sombra golpea otra vez ({v} del daño del arma)",
  "Wirst du getroffen: Druckwelle mit {v} Waffenschaden, höchstens alle {s} s": "Si te golpean: onda expansiva con {v} del daño del arma, como mucho cada {s} s",
  "{p} je kritischem Treffer: Klingenwirbel um dich, 1,4 s lang je {v} Waffenschaden": "{p} de prob. por crítico: remolino de hojas a tu alrededor durante 1,4 s, {v} del daño del arma por golpe",
  "Fächerschuss: Pfeile +{n}": "Disparo en abanico: flechas +{n}",
  "Giftklingen: Messer +{n}": "Hojas venenosas: cuchillos +{n}",
  "Kettenblitz: Sprünge +{n}": "Rayo en cadena: saltos +{n}",
  "Feuerball +{v} Schaden und ein zweiter Feuerball": "Bola de fuego +{v} de daño y una segunda bola de fuego",
  "Feuerball +{v} Schaden": "Bola de fuego +{v} de daño",
  "Pfeilsturm: Pfeile je Salve +{n}": "Tormenta de flechas: flechas por salva +{n}",
  "{skills}: Radius +{v}": "{skills}: radio +{v}",
  "{skills}: Schaden +{v}": "{skills}: daño +{v}",
  "{skills}: Abklingzeit −{c}, Schaden +{v}": "{skills}: enfriamiento −{c}, daño +{v}",
  "{skill} +{n} s": "{skill} +{n} s",
  "Fähigkeiten kosten {v} weniger": "Las habilidades cuestan {v} menos",
