  "Keine Affix-Essenz für Rüstung und Helm. Du bekommst welche unter EXTRAHIEREN – aus einer anderen Rüstung oder einem Helm.": "No tienes esencias de afijo para armadura y casco. Las consigues en EXTRAER, de otra armadura o de un casco.",
