  "Seil": "Cuerda",
  "Ein Kletterseil mit Wurfhaken – damit kommst du an den Übergängen über Schluchten.": "Una cuerda de escalada con garfio: con ella cruzas los abismos por los pasos.",
  "Brückenstein": "Piedra puente",
  "Ein Stein der Alten: Er lässt eingestürzte Brücken über reißende Flüsse wieder erstehen.": "Una piedra de los Antiguos: hace resurgir los puentes derrumbados sobre los ríos embravecidos.",
  "Kräutermaske": "Máscara de hierbas",
  "Filtert Giftnebel und Giftluft. Ohne sie brennt jeder Atemzug.": "Filtra la niebla tóxica y el aire tóxico. Sin ella, cada bocanada quema.",
  "Eishaken": "Garfio de hielo",
  "Steigeisen und Haken: Damit erklimmst du Eisklippen an den markierten Stellen.": "Crampones y garfios: con ellos escalas los acantilados de hielo en los puntos marcados.",
  "Feuermantel": "Manto de fuego",
  "Schützt vor Lava, Hitze und eisiger Kälte. Über Lavaströme führen Trittsteine.": "Protege de la lava, el calor y el frío glacial. Los ríos de lava se cruzan sobre piedras pasaderas.",
  "Schattenlaterne": "Farol de sombras",
  "Ihr Licht durchdringt die lebendige Finsternis und vertreibt die Dunkelheit.": "Su luz atraviesa las tinieblas vivientes y ahuyenta la oscuridad.",
  "Gezeitenperle": "Perla de las mareas",
  "Teilt die Fluten: An den Pfeilern der Alten trägt dich das Wasser.": "Divide las aguas: junto a los pilares de los Antiguos, el agua te sostiene.",
  "Dornenklinge": "Filo de espinas",
  "Schneidet Wege durch Dornenwälle, die nichts anderes durchdringt.": "Abre camino a través de muros de espinas que nada más puede atravesar.",
  "Sturmfeder": "Pluma de tormenta",
  "Hält dich im Auge des Sturms – Sturmwände und Böen werfen dich nicht mehr zurück.": "Te mantiene en el ojo de la tormenta: los muros de tormenta y las ráfagas ya no te hacen retroceder.",
  "Sternenschlüssel": "Llave estelar",
  "Öffnet die uralten Siegel der Sternentore.": "Abre los sellos ancestrales de los portales estelares.",
  "Leere-Anker": "Ancla del vacío",
  "Verankert dich in der Wirklichkeit – über Leere-Risse und durch das Nichts.": "Te ancla a la realidad: sobre las grietas del vacío y a través de la Nada.",
  "Seil II": "Cuerda II",
  "Ein Seil aus Sternenfaden mit Kristallhaken – es hält auch über der Kristallkluft, wo jedes andere Seil zerschneidet.": "Una cuerda de hilo estelar con garfio de cristal: aguanta incluso sobre la Sima de cristal, donde cualquier otra cuerda se corta.",
  "Kräutermaske II": "Máscara de hierbas II",
  "Gefüllt mit Kräutern vom Rand der Welt: Sie filtert die Wand aus Blutnebel, den Blutdunst der Sümpfe und die Sporenluft der Pilzriesen.": "Rellena de hierbas del confín del mundo: filtra el muro de niebla de sangre, el vaho de sangre de los pantanos y el aire de esporas de los hongos gigantes.",
  "Eishaken II": "Garfio de hielo II",
  "Haken aus Himmelsstahl: Damit kletterst du am Himmelsabbruch entlang, und kein Höhensturm reißt dich fort.": "Garfios de acero celeste: con ellos trepas a lo largo del precipicio celeste y ninguna tormenta de altura te arrastra.",
  "Brückenstein II": "Piedra puente II",
  "Ein Stein der Alten, der Brücken über den Seelenstrom baut. Sein Licht hält auch den Seelensog von dir fern.": "Una piedra de los Antiguos que tiende puentes sobre el torrente de almas. Su luz también mantiene a raya el vórtice de almas.",
  "Feuermantel II": "Manto de fuego II",
  "Gewebt aus Sternenfeuer: schützt vor Sternenglut und Grabeskälte. Über die Glutströme führen schwebende Steine.": "Tejido con fuego estelar: protege de las ascuas estelares y del frío sepulcral. Los ríos de brasas se cruzan sobre piedras flotantes.",
  "Schattenlaterne II": "Farol de sombras II",
  "Ihr Licht weckt dich aus jedem Traum: Sie zerreißt den Traumschleier und vertreibt den Traumnebel.": "Su luz te despierta de cualquier sueño: rasga el velo de los sueños y ahuyenta la bruma onírica.",
  "Gezeitenperle II": "Perla de las mareas II",
  "Eine Perle aus erstarrter Zeit: An den Stundenpfeilern hält sie den Zeitstrom an und schützt vor dem Zeitsog.": "Una perla de tiempo congelado: junto a los pilares de las horas detiene la corriente del tiempo y te protege del vórtice del tiempo.",
  "Dornenklinge II": "Filo de espinas II",
  "Geschmiedet aus Sternensplittern: Sie schneidet Wege durch Splitterwälle und zerschlägt den Splitterregen.": "Forjado con esquirlas de estrella: abre camino a través de muros de esquirlas y hace añicos la lluvia de esquirlas.",
  "Sternenschlüssel II": "Llave estelar II",
  "Der Schlüssel zum Siegel der Welt. Dahinter liegt nur noch der Weltenrand – und das Ende der Welt.": "La llave del Sello del Mundo. Más allá solo queda el Borde del mundo… y el Fin del mundo.",
