  "Giftluft": "Aire tóxico",
  "Giftluft! Ohne Kräutermaske brennt jeder Atemzug.": "¡Aire tóxico! Sin Máscara de hierbas, cada bocanada quema.",
  "Eisige Kälte": "Frío glacial",
  "Eisige Kälte! Ohne Feuermantel wirst du langsam und frierst.": "¡Frío glacial! Sin Manto de fuego te vuelves lento y te congelas.",
  "Glühende Hitze": "Calor abrasador",
  "Glühende Hitze! Ohne Feuermantel versengt sie dich.": "¡Calor abrasador! Sin Manto de fuego, te abrasa.",
  "Finsternis! Ohne Schattenlaterne siehst du kaum die Hand vor Augen.": "¡Tinieblas! Sin Farol de sombras apenas ves tu propia mano.",
  "Sturm": "Tormenta",
  "Sturm! Ohne Sturmfeder werfen dich die Böen umher.": "¡Tormenta! Sin Pluma de tormenta, las ráfagas te zarandean.",
  "Sog der Leere": "Succión del vacío",
  "Die Leere saugt an deiner Kraft! Ohne Leere-Anker schwindet sie.": "¡El vacío te absorbe la fuerza! Sin Ancla del vacío, se desvanece.",
  "Blutdunst": "Vaho de sangre",
  "Blutdunst! Ohne Kräutermaske II saugt er dir das Leben aus.": "¡Vaho de sangre! Sin Máscara de hierbas II, te chupa la vida.",
  "Sporenluft": "Aire de esporas",
  "Sporenluft! Ohne Kräutermaske II vergiftet sie dich.": "¡Aire de esporas! Sin Máscara de hierbas II, te envenena.",
  "Höhensturm": "Tormenta de altura",
  "Höhensturm! Ohne Eishaken II reißt er dich von den Füßen.": "¡Tormenta de altura! Sin Garfio de hielo II, te derriba.",
  "Seelensog": "Vórtice de almas",
  "Seelensog! Ohne Brückenstein II zehren die Seelen an Kraft und Leben.": "¡Vórtice de almas! Sin Piedra puente II, las almas consumen tu fuerza y tu vida.",
  "Sternenglut! Ohne Feuermantel II verbrennst du.": "¡Ascuas estelares! Sin Manto de fuego II, ardes.",
  "Grabeskälte": "Frío sepulcral",
  "Grabeskälte! Ohne Feuermantel II erstarrst du.": "¡Frío sepulcral! Sin Manto de fuego II, te congelas.",
  "Traumnebel": "Bruma onírica",
  "Traumnebel! Ohne Schattenlaterne II wirst du müde und siehst kaum etwas.": "¡Bruma onírica! Sin Farol de sombras II, te entra sueño y apenas ves nada.",
  "Zeitsog": "Vórtice del tiempo",
  "Zeitsog! Ohne Gezeitenperle II zerrt die Zeit an dir.": "¡Vórtice del tiempo! Sin Perla de las mareas II, el tiempo tira de ti.",
  "Splitterregen": "Lluvia de esquirlas",
  "Splitterregen! Ohne Dornenklinge II schneiden dich die Splitter.": "¡Lluvia de esquirlas! Sin Filo de espinas II, las esquirlas te cortan.",
