  "DAS TOR ÖFFNET SICH …": "EL PORTAL SE ABRE …",
  "Das Tor flackert – versuch es noch einmal.": "El portal parpadea: inténtalo de nuevo.",
  "Tipp: Je weiter du dich vom Weltentor entfernst, desto stärker die Gegner – und desto besser die Beute.": "Consejo: cuanto más te alejes del Portal del Mundo, más fuertes serán los enemigos… y mejor el botín.",
  "Dein letzter Ausflug endete mitten im Kampf – die Lande haben dich verschlungen. Ausrüstung und Rucksack sind verloren.": "Tu última incursión terminó en pleno combate: las Tierras te devoraron. Has perdido el equipo y la mochila.",
  "Dein letzter Ausflug in die Endlosen Lande wurde unterbrochen: Der Rucksack ist verloren, deine Ausrüstung vom Aufbruch hast du noch.": "Tu última incursión en las Tierras Infinitas se interrumpió: la mochila se ha perdido, pero conservas el equipo con el que partiste.",
  "Dein Begleiter hat noch Beute aus den Landen dabei – sie liegt jetzt bei dir.": "Tu compañero aún traía botín de las Tierras: ahora es tuyo.",
