  "Rucksack": "Mochila",
  "ST. {n}": "NV. {n}",
  "Belohnung bei einer Kundschafterin": "Recompensa con una exploradora",
  "Rucksack & Ausrüstung": "Mochila y equipo",
  "Leuchtfeuer setzen ({n})": "Encender fuego guía ({n})",
  "Ausflug abbrechen": "Abandonar incursión",
  "Tippe etwas an: anlegen, in die Begleiter-Tasche legen oder wegwerfen.": "Toca algo para equiparlo, guardarlo en la bolsa del compañero o tirarlo.",
  "In die Begleiter-Tasche": "Dar al compañero",
  "Tasche voll": "Bolsa llena",
  "In den Rucksack": "A la mochila",
  "Wirklich wegwerfen?": "¿Tirar de verdad?",
  "Wegwerfen": "Tirar",
  "Wert: {n} Gold": "Valor: {n} de oro",
  "sicher in der Tasche": "a salvo en la bolsa",
  "geht beim Tod verloren": "se pierde al morir",
  "BEGLEITER-TASCHE {n}/{max}": "BOLSA DEL COMPAÑERO {n}/{max}",
  "{name} bringt das heim – auch wenn du fällst.": "{name} lo llevará a casa, aunque caigas.",
  "Keine Plätze.": "Sin espacios.",
  "Kein Begleiter dabei: Stirbst du, ist alles verloren.": "No llevas compañero: si mueres, lo pierdes todo.",
  "Ohne Begleiter-Tasche: Stirbst du, ist alles verloren.": "Sin bolsa de compañero: si mueres, lo pierdes todo.",
  "RUCKSACK {n}/{max}": "MOCHILA {n}/{max}",
  "Wirklich {n} wegwerfen?": "¿Tirar {n} de verdad?",
  "Plunder wegwerfen ({n})": "Tirar chatarra ({n})",
  "Rückkehrrolle lesen ({n})": "Leer pergamino ({n})",
  "{n} Dinge weggeworfen": "{n} objetos tirados",
  "Ein Rückweg öffnet sich unter deinen Füßen – bleib stehen!": "Un camino de vuelta se abre bajo tus pies: ¡no te muevas!",
  "MITTEN IM KAMPF!": "¡EN PLENO COMBATE!",
  "Abbrechen geht nur, wenn dich gerade nichts angreift. Lauf weg oder kämpfe!": "Solo puedes abandonar si nada te está atacando. ¡Huye o lucha!",
  "AUSFLUG ABBRECHEN?": "¿ABANDONAR LA INCURSIÓN?",
  "Der Rucksack bleibt in den Landen, und was du seit dem letzten Leuchtfeuer erkundet hast, ist vergessen. Du behältst die Ausrüstung, mit der du aufgebrochen bist, und alles in der Begleiter-Tasche.": "La mochila se queda en las Tierras, y olvidarás lo que hayas explorado desde el último fuego guía. Conservas el equipo con el que partiste y todo lo que hay en la bolsa del compañero.",
  "Ja, abbrechen": "Sí, abandonar",
  "Weiter erkunden": "Seguir explorando",
  "Ausflug abgebrochen – {n} Dinge sind verloren.": "Incursión abandonada: se han perdido {n} objetos.",
  "Ausflug abgebrochen.": "Incursión abandonada.",
  "Du hast keinen Leuchtfeuerstein. Sie liegen selten in Truhen, bei Bossen und bei Händlern.": "No tienes ninguna piedra de fuego guía. Se encuentran rara vez en cofres, en jefes y en mercaderes.",
  "Nicht mitten im Kampf!": "¡No en pleno combate!",
  "Hier ist kein fester Boden.": "Aquí no hay suelo firme.",
  "Zu nah an einem Ausgang, Lager oder Leuchtfeuer.": "Demasiado cerca de una salida, un campamento o un fuego guía.",
  "LEUCHTFEUER SETZEN": "ENCENDER FUEGO GUÍA",
  "{n} STEINE": "{n} PIEDRAS",
  "Ein Leuchtfeuer kostet einen Leuchtfeuerstein und brennt für immer.": "Un fuego guía cuesta una piedra de fuego guía y arde para siempre.",
  "Die Karte bis hierher wird gesichert – auch wenn du später fällst.": "El mapa hasta aquí queda guardado, aunque caigas después.",
  "Beim nächsten Ausflug kannst du hier starten.": "En tu próxima incursión podrás empezar aquí.",
  "Es ist ein Ausgang: hineinstellen und warten – die Beute ist sicher.": "Es una salida: colócate dentro y espera; el botín estará a salvo.",
  "{d} vom Weltentor": "A {d} del Portal del Mundo",
  "Du hast schon {n} Leuchtfeuer – das am längsten unbenutzte erlischt: {name}": "Ya tienes {n} fuegos guía: se apagará el que lleva más tiempo sin usarse: {name}",
  "Leuchtfeuer: {n} von {max}": "Fuegos guía: {n} de {max}",
  "Entzünden (1 Leuchtfeuerstein)": "Encender (1 piedra de fuego guía)",
  "LEUCHTFEUER ENTZÜNDET": "FUEGO GUÍA ENCENDIDO",
  "Karte gesichert ({n} neue Regionen). Hier startest du beim nächsten Mal – und hier kommst du raus.": "Mapa guardado ({n} regiones nuevas). La próxima vez empezarás aquí… y por aquí podrás salir.",
  "Leuchtfeuer / Ausgang": "Fuego guía / Salida",
  "Außenposten": "Puesto avanzado",
  "Übergang": "Paso",
  "Werkzeug-Hort": "Cámara de herramienta",
  "für dich {r}": "para ti: {r}",
  "{d} vom Weltentor · Tiefe {p} %": "A {d} del Portal del Mundo · Profundidad {p} %",
  "Regionen entdeckt: {n} · weiteste Reise: {d}": "Regiones descubiertas: {n} · viaje más lejano: {d}",
  "KARTE DER LANDE": "MAPA DE LAS TIERRAS",
  "Näher": "Acercar",
  "Weiter weg": "Alejar",
  "Zur Mitte": "Centrar",
  "noch nicht gesichert": "aún sin guardar",
  "NOCH UNERFORSCHT": "SIN EXPLORAR",
  "{d} breit": "{d} de ancho",
  "Kundschafterinnen in den Außenposten haben Aufträge für dich.": "Las exploradoras de los puestos avanzados tienen misiones para ti.",
  "AUFTRÄGE": "MISIONES",
  "Belohnung: {rep} Ruf, {items}": "Recompensa: {rep} de reputación, {items}",
  "Schlüssel": "Llave",
  "Belohnung nehmen": "Cobrar recompensa",
  "Gerücht über eine Spur": "Rumor de un rastro",
  "Tipp: Erfüllte Aufträge zahlen hier – oder automatisch, wenn du lebend durch einen Ausgang gehst.": "Consejo: las misiones cumplidas se cobran aquí… o automáticamente si cruzas una salida con vida.",
  "Gerücht: {tool}": "Rumor: {tool}",
  "Ein Hort mit diesem Werkzeug soll etwa {d} im {dir} liegen. Auf der Karte ist die Gegend markiert.": "Dicen que hay una cámara con esta herramienta a unos {d} al {dir}. La zona está marcada en el mapa.",
  "„Der Orden braucht Augen hier draußen. Erledige, was du kannst – bezahlt wird, wenn du es mir bringst oder lebend durch ein Tor gehst.“": "«La Orden necesita ojos aquí fuera. Haz lo que puedas: te pago cuando me lo traigas o cuando cruces un portal con vida.»",
  "RUF: {n}": "REPUTACIÓN: {n}",
  "Nächster Rang: {n} – {d}": "Siguiente rango: {n} – {d}",
  "+{n} Ruf bei den Kundschaftern": "+{n} de reputación con los exploradores",
  "Gib:": "Das:",
  "Heiltrank": "Poción de vida",
  "Kartenstück": "Fragmento de mapa",
  "Rückkehrrolle (Ausgang überall, doppelt so lange stehen)": "Pergamino de retorno (salida en cualquier lugar, el doble de espera)",
  "Leuchtfeuerstein (einer je Außenposten)": "Piedra de fuego guía (una por puesto avanzado)",
  "Bezahlt wird mit dem Gold in deinem Rucksack.": "Se paga con el oro de tu mochila.",
  "Leuchtfeuersteine verkaufen Händler erst ab dem Ruf „Bekannter“.": "Los mercaderes solo venden piedras de fuego guía a partir de la reputación «Conocido».",
  "Das Gold kommt in den Rucksack – raustragen musst du es trotzdem.": "El oro va a la mochila… aun así, tendrás que sacarlo de aquí.",
  "Dein Rucksack ist leer.": "Tu mochila está vacía.",
  "„Hier draußen zahlt man mit dem, was man trägt. Zeig her, was du hast.“": "«Aquí fuera se paga con lo que llevas encima. A ver qué tienes.»",
  "TAUSCH": "TRUEQUE",
  "KAUFEN": "COMPRAR",
  "VERKAUFEN": "VENDER",
  "Rucksack voll!": "¡Mochila llena!",
  "Getauscht: {n}": "Intercambiado: {n}",
  "Leuchtfeuerstein gekauft ({n})": "Piedra de fuego guía comprada ({n})",
  "„Setz dich ans Feuer. Die Lande nehmen viel – ein bisschen gebe ich zurück.“": "«Siéntate junto al fuego. Las Tierras quitan mucho… yo te devuelvo un poco.»",
  "LP {hp}/{max} · Tränke {n}/{m}": "PV {hp}/{max} · Pociones {n}/{m}",
  "Wunden versorgen (einmal frei)": "Curar heridas (una vez gratis)",
