  "Vollständig geheilt": "Curación completa",
  "Kräutersegen: Regeneration für 2 Minuten": "Bendición herbal: regeneración durante 2 minutos",
  "Mitte der Welt": "Centro del mundo",
  "Tasche mit {n} Plätzen – was darin liegt, überlebt deinen Tod.": "Bolsa de {n} espacios: lo que lleve dentro sobrevive a tu muerte.",
  "Hat keine Tasche.": "No tiene bolsa.",
  "{n} PLÄTZE": "{n} ESPACIOS",
  "{name} ist verletzt": "{name} está herido",
  "Kein Begleiter dabei": "Sin compañero",
  "Ruht sich noch {n} Minuten im Versteck aus.": "Descansa aún {n} minutos en la Guarida.",
  "Ohne Begleiter-Tasche ist bei deinem Tod alles verloren.": "Sin bolsa de compañero, al morir lo pierdes todo.",
  "FUNDKISTE ({n})": "ARCÓN ({n})",
  "Was beim letzten Mal keinen Platz mehr hatte.": "Lo que la última vez ya no cabía.",
  "Alles abholen": "Recoger todo",
  "WERKZEUGE {n}/{max}": "HERRAMIENTAS {n}/{max}",
  "Als Nächstes: {tool} – für {bar} etwa {d} vom Tor. Horte damit liegen diesseits davon.": "Siguiente: {tool}, para {bar}, a unos {d} del portal. Las cámaras con esta herramienta están a este lado.",
  "Du hast alle Werkzeuge. Die ganze Welt steht dir offen – bis an ihren Rand.": "Tienes todas las herramientas. El mundo entero está abierto para ti… hasta su borde.",
  "STARTPUNKT": "PUNTO DE PARTIDA",
  "LEUCHTFEUERSTEINE {n}": "PIEDRAS GUÍA {n}",
  "LEUCHTFEUER {n}/{max}": "FUEGOS GUÍA {n}/{max}",
  "SCHLÜSSEL {n}": "LLAVES {n}",
  "Karte der Lande": "Mapa de las Tierras",
  "WAS DU RISKIERST · {n} GOLD": "LO QUE ARRIESGAS · {n} ORO",
  "WAS ÜBERLEBT": "LO QUE SOBREVIVE",
  "Stirbst du, sind Ausrüstung und Rucksack verloren.": "Si mueres, pierdes el equipo y la mochila.",
  "Nur die Begleiter-Tasche kommt heim – dein Begleiter teleportiert mit dir zurück.": "Solo vuelve a casa la bolsa del compañero: tu compañero se teletransporta contigo.",
  "Raus kommst du durch ein Tor der Alten, das Weltentor oder ein Leuchtfeuer: hineinstellen und warten.": "Sales por un portal de los Antiguos, el Portal del Mundo o un fuego guía: colócate dentro y espera.",
  "Die Karte wird nur gesichert, wenn du ein Leuchtfeuer setzt oder entkommst – wer fällt, vergisst den Weg seit dem letzten Leuchtfeuer.": "El mapa solo se guarda si enciendes un fuego guía o escapas: quien cae olvida el camino recorrido desde el último fuego guía.",
  "Abbrechen geht nur außerhalb des Kampfes – wer mitten im Kampf das Spiel schließt, fällt.": "Solo puedes abandonar fuera de combate: quien cierra el juego en pleno combate, cae.",
  "Noch {n} Ruf bis {r}: {d}": "Faltan {n} de reputación para {r}: {d}",
  "AUSFLÜGE {n}": "INCURSIONES {n}",
  "ENTKOMMEN {n}": "HUIDAS {n}",
  "GEFALLEN {n}": "CAÍDAS {n}",
  "BESTE BEUTE {n}": "MEJOR BOTÍN {n}",
  "REGIONEN {n}": "REGIONES {n}",
  "WEITESTE REISE {d}": "MÁS LEJOS {d}",
  "GRENZEN {n}/{m}": "FRONTERAS {n}/{m}",
  "ENDE DER WELT ERREICHT": "FIN DEL MUNDO ALCANZADO",
  "Betreten: {n}": "Entrar: {n}",
  "Ab Level {n} – dir fehlen noch {m}": "Desde nivel {n}: te faltan {m}",
  "Hinter dem Tor liegen die Endlosen Lande: eine Welt ohne Ende, für alle dieselbe – die beste Beute, aber wer dort stirbt, verliert, was er trägt.": "Tras el portal se extienden las Tierras Infinitas: un mundo sin fin, el mismo para todos. El mejor botín… pero quien muere allí pierde lo que lleva encima.",
  "DIE ENDLOSEN LANDE": "LAS TIERRAS INFINITAS",
  "Die beste Beute – aber wer dort stirbt, verliert, was er trägt.": "El mejor botín… pero quien muere allí pierde lo que lleva encima.",
  "{n} Dinge abgeholt": "{n} objetos recogidos",
  "Endlose Lande": "Tierras Infinitas",
  "ab LV 5": "desde LV 5",
  "Torhüterin Ysra": "Guardiana Ysra",
  "Hinter dem Tor liegen die Endlosen Lande. Wer dort fällt, kommt nackt zurück – wenn überhaupt.": "Tras el portal se extienden las Tierras Infinitas. Quien cae allí vuelve desnudo… si es que vuelve.",
  "Nimm deinen Begleiter mit. Was in seiner Tasche steckt, bringt er immer heim.": "Llévate a tu compañero. Lo que guarde en su bolsa siempre lo trae de vuelta a casa.",
  "Je weiter du gehst, desto härter wird es. Ein Leuchtfeuer sichert den Weg, den du gegangen bist.": "Cuanto más lejos vayas, más duro será. Un fuego guía asegura el camino que has recorrido.",
  "Schluchten, Flüsse, Giftnebel … ohne das richtige Werkzeug kommst du nicht weiter. Die Kundschafterinnen wissen, wo eins liegt.": "Abismos, ríos, niebla tóxica… sin la herramienta adecuada no avanzarás. Las exploradoras saben dónde encontrar una.",
  "Zwanzig Grenzen liegen zwischen hier und dem Rand. Hinter der elften helfen nur noch Meisterwerkzeuge – und am Ende der Welt wartet ein Denkmal auf den, der so weit kommt.": "Veinte fronteras separan este lugar del confín. Pasada la undécima, solo sirven las herramientas maestras… y en el Fin del mundo aguarda un monumento a quien llegue tan lejos.",
  "Frühbieter": "Madrugador",
  "Stetig": "Constante",
  "Last-Minute": "Último minuto",
  "Sammler": "Coleccionista",
  "Schnäppchenjäger": "Cazagangas",
  "Krämer": "Buhonero",
  "Kaufmann": "Comerciante",
  "Großhändler": "Mayorista",
  "Handelsherr": "Señor del comercio",
  "Gildenmeister": "Maestro del gremio",
