  "Goldkönig": "Rey del Oro",
  "Legende des Basars": "Leyenda del Bazar",
  "Auktionatorin Hedda": "Subastadora Hedda",
  "Alles hat seinen Preis, {name}. Die Kunst ist, ihn vor den anderen zu kennen.": "Todo tiene un precio, {name}. El arte está en conocerlo antes que los demás.",
  "Kaspar bietet immer in der letzten Minute. Halt die Augen offen.": "Kaspar siempre puja en el último minuto. Mantén los ojos abiertos.",
  "Wer versteigert, braucht Geduld. Wer bietet, braucht Nerven.": "Quien subasta necesita paciencia. Quien puja, nervios de acero.",
  "Ein Legendärer unter Marktwert? Kommt vor. Selten. Aber es kommt vor.": "¿Un legendario por debajo de su valor de mercado? Pasa. Pocas veces. Pero pasa.",
  "Grimbart sammelt alles, was glänzt – und zahlt dafür fast jeden Preis.": "Grimbart colecciona todo lo que brilla… y paga casi cualquier precio por ello.",
  "Mein Hammer fällt, wenn die Zeit um ist. Keine Sekunde früher.": "Mi martillo cae cuando se acaba el tiempo. Ni un segundo antes.",
  "Marktwert: {n} Gold": "Valor de mercado: {n} de oro",
  "Handelsrang {n}: {title}! Weniger Gebühr, mehr Plätze.": "¡Rango comercial {n}: {title}! Menos comisión, más espacios.",
  "Bauteil für die Schmiede": "Pieza para la Forja",
  "Kommt in dein Brutnest. Gut gepflegt schlüpft daraus ein Begleiter.": "Va a tu Nido. Si lo cuidas bien, de él saldrá un compañero.",
