  "Versteigerung verloren: {item} ging für {n} Gold an {name}.": "Subasta perdida: {item} fue para {name} por {n} de oro.",
  "Basar: {n} weitere Neuigkeiten – siehe MEINE.": "Bazar: {n} novedades más; míralas en MÍO.",
  "ZUSCHLAG!": "¡ADJUDICADO!",
