  "Zu wenig Gold.": "No tienes oro suficiente.",
  "Beutel und Lager sind voll. Mach zuerst Platz.": "La bolsa y el alijo están llenos. Primero haz sitio.",
  "Dein Brutnest ist voll.": "Tu Nido está lleno.",
  "Eier kann diese Version noch nicht annehmen.": "Esta versión aún no puede recibir huevos.",
  "Das ist nicht mehr da.": "Eso ya no está.",
  "Diese Versteigerung ist schon vorbei.": "Esta subasta ya ha terminado.",
  "Du hast schon das höchste Gebot.": "Ya tienes la puja más alta.",
  "Das Gebot ist zu niedrig.": "La puja es demasiado baja.",
  "Alle Auktionsplätze sind belegt. Ein höherer Handelsrang bringt mehr.": "Todos tus espacios de subasta están ocupados. Un rango comercial más alto te da más.",
  "Wähle zuerst einen Helden.": "Primero elige un héroe.",
  "Es gibt schon Gebote – die Versteigerung läuft bis zum Ende.": "Ya hay pujas: la subasta sigue hasta el final.",
  "{item} liegt im Beutel.": "{item} está en la bolsa.",
