  "1 Sache wartet auf dich – antippen zum Abholen.": "1 cosa te espera: toca para recogerla.",
  "{n} Sachen warten auf dich – antippen zum Abholen.": "{n} cosas te esperan: toca para recogerlas.",
  "Die Uhr deines Geräts wurde zurückgestellt. Der Basar wartet, bis sie wieder stimmt (noch {t}).": "El reloj de tu dispositivo se ha atrasado. El Bazar esperará hasta que vuelva a estar bien (faltan {t}).",
