  "AUSVERKAUFT": "AGOTADO",
  "Tippe ein Angebot an, um es genau anzusehen. Gekauftes kommt in den Beutel – ist er voll, ins Lager.": "Toca una oferta para verla en detalle. Lo que compres va a la bolsa; si está llena, al alijo.",
  "Kaufen": "Comprar",
