  "Nur solange der Vorrat reicht.": "Hasta agotar existencias.",
  "GEGENSTÄNDE": "OBJETOS",
  "MATERIAL": "MATERIALES",
  "Sofort verkaufen bringt Gold auf die Hand. Versteigern bringt meist mehr – dauert aber.": "Vender al instante te da oro en mano. Subastar suele dar más… pero tarda.",
  "Sicher? {n} Gegenstände für {g} Gold": "¿Seguro? {n} objetos por {g} de oro",
