  "So teuer will das wohl niemand – senk den Startpreis.": "A ese precio no lo querrá nadie: baja el precio de salida.",
  "Längere Versteigerungen finden mehr Bieter. Die Gebühr zahlst du nur, wenn verkauft wird. Unverkauftes kommt ins Abholfach zurück.": "Las subastas más largas encuentran más pujadores. La comisión solo la pagas si se vende. Lo que no se vende vuelve al buzón.",
  "Versteigerung starten": "Iniciar subasta",
  "Alle {n} Auktionsplätze belegt": "Los {n} espacios de subasta están ocupados",
  "Start {n} Gold · noch kein Gebot": "Salida {n} de oro · sin pujas",
