  "ÜBERBOTEN": "SUPERADO",
  "VERLÄNGERT": "AMPLIADA",
  "Sofort {n}": "Compra ya {n}",
  "Gerade läuft keine Versteigerung. Schau gleich noch mal vorbei.": "Ahora no hay ninguna subasta. Vuelve a pasarte en un rato.",
  "Biete gegen andere Händler. Dein Gebot wird reserviert – wirst du überboten, bekommst du es zurück.": "Puja contra otros mercaderes. Tu puja queda reservada: si te superan, te la devuelven.",
  "Tippe eine Versteigerung an, um zu bieten. Kurz vor Schluss wird oft noch geboten – dann verlängert sich die Zeit.": "Toca una subasta para pujar. Al final suele haber pujas de última hora, y entonces el tiempo se amplía.",
