  "Die Gerüste dort? Dort bauen wir Schmiede, Labor, Schatzkammer und mehr. Geh hin und sieh, was es kostet.": "¿Ves esos andamios? Ahí construiremos la forja, el laboratorio, la cámara del tesoro y más. Acércate y mira cuánto cuesta.",
