  "Antippen zum Auswählen, nochmal antippen zum Verschieben. Das Lager teilen sich alle deine Helden.": "Toca para seleccionar y vuelve a tocar para mover. Todos tus héroes comparten el alijo.",
  "Ins Lager legen": "Guardar en el alijo",
  "In den Beutel": "A la bolsa",
  "Tippe einen Gegenstand an.": "Toca un objeto.",
  "Dauerhafter Bonus für alle Helden: {bonus}. Schlag die Trainingspuppe, um deinen Schaden pro Sekunde zu sehen.": "Bonificación permanente para todos tus héroes: {bonus}. Golpea el muñeco de entrenamiento para ver tu daño por segundo.",
  "+{n} % Schaden und LP": "+{n} % de daño y PV",
  "Die Kumpel fördern für jeden geschafften Raum (bis zu 25).": "Los mineros extraen por cada sala superada (hasta 25).",
  "Der Garten wächst für jeden geschafften Raum (bis zu 25).": "El huerto crece por cada sala superada (hasta 25).",
  "Seit dem letzten Besuch: {n}.": "Desde tu última visita: {n}.",
