  "{n} Räume": "{n} salas",
  "Einsammeln": "Recoger",
  "Noch nichts zum Einsammeln. Schaff ein paar Räume!": "Aún no hay nada que recoger. ¡Supera algunas salas!",
  "Eingesammelt!": "¡Recogido!",
  "CHRONIK {n}/{max}": "CRÓNICA {n}/{max}",
  "GESCHICHTE": "HISTORIA",
  "BESTIARIUM": "BESTIARIO",
  "Chronikseiten findest du in Truhen, bei Elite-Gegnern, Bossen und in Gräbern. Ab Bibliothek-Stufe 3 häufiger.": "Encontrarás páginas de la Crónica en cofres, enemigos de élite, jefes y tumbas. Desde el nivel 3 de la Biblioteca, con más frecuencia.",
  "Prolog": "Prólogo",
  "Akt {act}: {title}": "Acto {act}: {title}",
  "Die Qual": "El Tormento",
  "1 GLÜCKSMÜNZE": "1 MONEDA DE LA FORTUNA",
  "{n} GLÜCKSMÜNZEN": "{n} MONEDAS DE LA FORTUNA",
  "REINER ZUFALL": "PURA SUERTE",
  "GLÜCKSROLLE": "RULETA DE LA FORTUNA",
  "Gratis-Dreh der Glückswoche!": "¡Giro gratis de la Semana de la Fortuna!",
  "Gratis drehen!": "¡Girar gratis!",
  "Glücksrolle drehen (1 {coin})": "Girar la ruleta (1 {coin})",
  "1 {coin} kaufen ({gold} Gold)": "Comprar 1 {coin} ({gold} de oro)",
  "SCHICKSALSTRUHEN": "COFRES DEL DESTINO",
  "Glücksmünzen gibt es von Bossen, Champions, seltenen Truhen, der Tages-Challenge und Schreinen Fortunas. Jede Drehung ist reiner Zufall mit den gezeigten Chancen – Mythisch kann beim ersten Dreh kommen oder erst nach sehr vielen.": "Las Monedas de la Fortuna se obtienen de jefes, campeones, cofres raros, el Desafío diario y los Santuarios de Fortuna. Cada tirada es pura suerte con las probabilidades mostradas: lo Mítico puede salir en la primera tirada o tras muchísimas.",
  "Alle Kosmetik gesammelt – 4 Glücksmünzen zurück": "Ya tienes todos los cosméticos: recuperas 4 Monedas de la Fortuna",
  "Kosmetik: {name} (im Spiegel anlegen)": "Cosmético: {name} (equípalo en el espejo)",
