  "Knöpfe ziehen zum Verschieben · antippen zum Auswählen": "Arrastra los botones para moverlos · toca para seleccionar",
  "nicht für deine Klasse": "no es para tu clase",
  "STEUERUNG": "CONTROLES",
  "Linke Seite ziehen: laufen. Angriff halten (3er-Kombo) – über den Knopf wischen zielt von Hand. Rolle, drei Fähigkeiten, Ultimative (goldene Wut-Leiste). Der Trank sitzt links oben. Alle Knöpfe lassen sich unter Einstellungen → Steuerung verschieben.": "Arrastra en el lado izquierdo: caminar. Mantén Ataque (combo de 3); desliza sobre el botón para apuntar a mano. Rodar, tres habilidades y Definitiva (barra dorada de Furia). La poción está arriba a la izquierda. Puedes mover todos los botones en Ajustes → Controles.",
  "WASD laufen · Linke Maustaste angreifen (halten: Kombo) · Rechte Maustaste rollen · Angriffe und Fähigkeiten zielen auf den Mauszeiger · 1 2 3 Fähigkeiten · 4 Ultimative · 5 Trank · E Interagieren · C Charakter · Esc Pause": "WASD moverse · Botón izquierdo atacar (mantener: combo) · Botón derecho rodar · Ataques y habilidades apuntan al cursor · 1 2 3 habilidades · 4 definitiva · 5 poción · E interactuar · C personaje · Esc pausa",
  "Auch: J/Leertaste angreifen · Shift/K rollen · F Ultimative · H Trank": "También: J/Espacio atacar · Shift/K rodar · F definitiva · H poción",
  "Grafik: „16x16 DungeonTileset II“ von 0x72, Zauber-Effekte „Pixel Art Spells“, „Pixel Art Sword Slash“ und Explosionen von OpenGameArt – alle CC0.": "Gráficos: «16x16 DungeonTileset II» de 0x72; efectos de hechizos «Pixel Art Spells», «Pixel Art Sword Slash» y explosiones de OpenGameArt, todos CC0.",
