  "Der Uralte Drache hat das Weltenfeuer gestohlen. Bau dein Versteck wieder auf, schmiede Klingen aus Mithril, Adamant und Drachenschuppen – und hol dir zurück, was dem Orden gehört.": "El Dragón Ancestral ha robado el Fuego del Mundo. Reconstruye tu Guarida, forja armas de mitril, adamantio y escamas de dragón… y recupera lo que pertenece a la Orden.",
