  "Ab Level 50 sammelst du Paragon-Erfahrung. Jeder Paragon-Level gibt einen Punkt – ohne Obergrenze.": "A partir del nivel 50 acumulas experiencia Paragon. Cada nivel Paragon te da un punto, sin límite.",
