  "„Mein Vetter. Gute Ware, faire Preise. Meistens.“": "«Mi primo. Buena mercancía, precios justos. Casi siempre».",
  "SCHREIN": "SANTUARIO",
  "Drei Altäre leuchten im Halbdunkel. Du kannst nur einen berühren.": "Tres altares brillan en la penumbra. Solo puedes tocar uno.",
  "Nichts berühren": "No tocar nada",
  "RASTPLATZ": "CAMPAMENTO",
  "Ein Lagerfeuer knistert. Du hast dich erholt (+40 % LP). Wofür nutzt du die Nacht?": "Una hoguera crepita. Te has recuperado (+40 % de PV). ¿En qué usarás la noche?",
