  "Geschichten lauschen (Chronikseite oder Erfahrung)": "Escuchar historias (página de la Crónica o experiencia)",
  "RÄTSELKAMMER": "CÁMARA DEL ENIGMA",
  "Richtig: Glücksmünze, Edelstein und Gold. Falsch: Die Sphinx lässt ihre Wächter los.": "Si aciertas: Moneda de la Fortuna, gema y oro. Si fallas: la Esfinge suelta a sus guardianes.",
  "Ein Edelstein glitzert im Wasser!": "¡Una gema brilla en el agua!",
