  "Kopiere den Code auf einem Gerät und füge ihn auf dem anderen ein. Er enthält alle Helden, das Versteck, Erfolge und das Bestiarium. Alte Codes aus Version 1 bis 3 funktionieren auch.": "Copia el código en un dispositivo y pégalo en el otro. Incluye todos los héroes, la Guarida, los logros y el Bestiario. Los códigos antiguos de las versiones 1 a 3 también funcionan.",
